"""Hand / finger ligament rows, flexor pulleys, extensor mechanism, and fascial passages of the limbs."""
from rows_common import P, S

# =================================================================== FINGER COLLATERAL LIGAMENTS - owner example (proper + accessory + volar plate)
_PIP = "collateral_interphalangeal_ligaments_of_hand"   # Z-Anatomy structure id (no own-body mesh; the data layer has no PIP/DIP record)
P(_PIP, "pip_proper_collateral", "ligament_component", "PIP proper collateral ligament", "Arises widely from dorsal and proximal to the fovea on the side of the proximal phalangeal head and inserts along most of the side of the base of the middle phalanx; stout; fibres parallel to the middle phalanx in all joint positions (differs from most line drawings).",
  ["allison2005", "pang2018"], cls="ligament", ev="microscope dissection n=8 PIP joints + 2 histology", setid="finger_collateral.pairs", z=["zan_collateral_interphalangeal_ligaments_of_hand_{s}"], geom=dict(rule="z_part_mesh"),
  note="Z-Anatomy has one mesh per hand for ALL interphalangeal collaterals (proper + accessory not separated): the position is the pooled centroid.")
P(_PIP, "pip_accessory_collateral", "ligament_component", "PIP accessory collateral ligament", "Less substantial; lies between the proper collateral ligament and the volar plate; suspends the plate laterally with the A3 pulley; contains the assemblage nuclei (mechanoreceptors).",
  ["allison2005", "pang2018", "lee2013pp", "chikenji2010"], cls="ligament", ev="dissection; 3-D reconstruction n=16; immunohistochemistry n=12", setid="finger_collateral.pairs")
P("palmar_interphalangeal_ligaments", "pip_volar_plate_distal_fibrous", "ligament_component", "PIP volar (palmar) plate: distal fibrous portion", "Distal fibrous portion anchoring to the base of the middle phalanx.", ["lee2013pp", "bowers1980"], cls="ligament", ev="3-D dissection n=16; n=60", setid="finger_collateral.pairs",
  z=["zan_palmar_interphalangeal_ligaments_{s}"], geom=dict(rule="z_part_mesh"))
P("palmar_interphalangeal_ligaments", "pip_volar_plate_proximal_membranous_checkrein", "ligament_component", "PIP volar plate: proximal membranous portion + check-rein ligaments", "Proximal membranous portion continuous with the bilateral check-rein ligaments; proximal attachments distinctive, distal attachments variable (Bowers).", ["lee2013pp", "bowers1980"], cls="ligament", ev="3-D dissection n=16; n=60")
P(_PIP, "dip_accessory_collateral", "ligament_component", "DIP accessory collateral ligament", "Contains the assemblage nuclei of the DIP joint; the C3 pulley contains their proximal region, the A5 pulley the middle and distal parts.", ["chikenji2011"], cls="ligament", ev="immunohistochemistry n=12 index DIP", setid="finger_collateral.pairs")
P(_PIP, "dip_proper_collateral", "ligament_component", "DIP proper collateral ligament", "By analogy with the PIP joint (proper + accessory + volar plate); not described in the cited DIP paper.", ["pang2018", "gray42"], ver="unverified", cls="ligament", ev="textbook / analogy", setid="finger_collateral.pairs")
S("finger_collateral.pairs", _PIP, "ligament_component", "Interphalangeal collateral system: components", [(3, "pang2018", "proper collateral, accessory collateral, volar plate (PIP)")])
_MCP = "finger_mcp_collateral_and_plate_complex"
P(_MCP, "mcp_proper_collateral", "ligament_component", "MCP proper collateral ligament (cord)", "Proper (cord) collateral ligament of the finger MCP joint, taut in flexion. NOT verified by a PubMed anatomy abstract in this search (only thumb MCP collaterals were).", ["gray42"], ver="unverified", cls="ligament", ev="textbook",
  z=["zan_collateral_metacarpophalangeal_ligaments_{s}"], geom=dict(rule="z_part_mesh"))
P(_MCP, "mcp_accessory_collateral", "ligament_component", "MCP accessory collateral ligament (fan)", "Accessory collateral ligament inserting into the volar plate.", ["gray42"], ver="unverified", cls="ligament", ev="textbook")
P(_MCP, "mcp_volar_plate", "ligament_component", "MCP volar (palmar) plate", "Fibrocartilaginous plate attached to the base of the proximal phalanx.", ["gray42"], ver="unverified", cls="ligament", ev="textbook")
P("thumb_mcp_ucl", "proper_collateral", "ligament_component", "Thumb MCP ulnar collateral ligament: proper", "Origin centre 4.2 mm from the dorsal surface and 5.3 mm from the articular surface of the metacarpal head; phalangeal insertion centre 2.8 mm from the volar surface and 3.4 mm from the articular surface (n=18).", ["carlson2012"], cls="ligament", ev="cadaver n=18 UCL", setid="thumb_ucl.parts")
P("thumb_mcp_ucl", "accessory_collateral", "ligament_component", "Thumb MCP ulnar collateral ligament: accessory", "A complete UCL tear involves both the proper and the accessory ligaments.", ["patel2019"], cls="ligament", ev="biomechanics n=8", setid="thumb_ucl.parts")
S("thumb_ucl.parts", "thumb_mcp_ucl", "ligament_component", "Thumb UCL: components", [(2, "patel2019", "proper + accessory")])
P("thumb_mcp_rcl", "proper_collateral", "ligament_component", "Thumb MCP radial collateral ligament: proper", "Origin centre 3.5 mm from the dorsal surface and 3.3 mm from the articular surface; insertion 2.8 mm from the volar surface, 2.6 mm from the articular surface (n=18).", ["carlson2012"], cls="ligament", ev="cadaver n=18 RCL")

# =================================================================== FLEXOR TENDON PULLEYS
for nm, ds in [("palmar_aponeurosis_pulley", "Palmar aponeurosis pulley (described by Manske and Lesker)."), ("a1", "First annular pulley (A1)."), ("a2", "Second annular pulley (A2)."), ("a3", "Third annular pulley (A3); at the PIP joint with C1 proximal."),
               ("a4", "Fourth annular pulley (A4)."), ("a5", "Fifth annular pulley (A5); contains the middle and distal regions of the DIP assemblage nuclei."), ("c1", "First cruciform pulley (C1); proximal region of the PIP assemblage nuclei."), ("c2", "Second cruciform pulley (C2)."), ("c3", "Third cruciform pulley (C3); proximal region of the DIP assemblage nuclei.")]:
    P("flexor_tendon_pulley_system_hand", nm, "ligament_component", ds, ds + " Doyle 1988: 61 fingers; palmar aponeurosis pulley, five annular and three cruciform pulleys.", ["doyle1988"] + (["chikenji2010", "chikenji2011"] if nm in ("a3", "a5", "c1", "c3") else []), cls="tendon", ev="fresh cadaver fingers n=61", setid="flexor_pulleys.parts",
      z=(["zan_cruciform_part_of_fibrous_sheath_of_digit_of_hand_{s}"] if nm.startswith("c") else []))
S("flexor_pulleys.parts", "flexor_tendon_pulley_system_hand", "ligament_component", "Finger flexor pulley system: pulleys", [(9, "doyle1988", "palmar aponeurosis pulley + 5 annular + 3 cruciform"), (4, "zafonte2014", "thumb pulley system: 4 components, not the classical 3")])
P("flexor_tendon_pulley_system_hand", "thumb_pulleys_four", "ligament_component", "Thumb pulley system: four components", "The thumb pulley system has 4 constituents, in contrast to the classic teaching of 3.", ["zafonte2014"], cls="tendon", ev="review", setid="flexor_pulleys.parts")

# =================================================================== INTRINSICS / EXTENSOR MECHANISM
for nm in ("dorsal_interossei_hand", "palmar_interossei"):
    pct = "75 %" if nm.startswith("dorsal") else "38 %"
    P(nm, "multiple_heads", "head_belly", "Additional heads (more than one head)", f"{pct} of these interossei had more than one head (14 fresh hands); up to three heads, each with a different distal destination.", ["eladou2002"], ev="cadaver n=14 hands", var=pct)
    P(nm, "insertion_bone", "insertion_point", "Distal insertion: bone (base of the proximal phalanx)", "Interossei insert on bone as well as the extensor apparatus (and, per Zancolli, the volar plate).", ["eladou2002"], ev="cadaver n=14 hands")
    P(nm, "insertion_extensor_apparatus", "insertion_point", "Distal insertion: extensor apparatus", "Insertion onto the extensor apparatus (lateral band / hood).", ["eladou2002"], ev="cadaver n=14", related=["extensor_hood"])
    P(nm, "insertion_volar_plate", "insertion_point", "Distal insertion: volar plate (assemblage nucleus)", "Additional insertion on the volar plate, described by Zancolli; palmar interossei too may insert on bone and volar plate.", ["eladou2002"], ev="cadaver n=14")
P("extensor_digitorum", "intertendinous_connection_2nd_space", "ligament_component", "Intertendinous connection, 2nd intermetacarpal space (usually type 1 filamentous)", "Most common pattern: type 1 (filamentous band).", ["hirai2001"], ev="cadaver n=548 limbs", var="type 1 most common", cls="muscle")
P("extensor_digitorum", "intertendinous_connection_3rd_space", "ligament_component", "Intertendinous connection, 3rd intermetacarpal space (usually type 3r)", "Most common: type 3r (tendinous, r-shaped).", ["hirai2001"], ev="cadaver n=548", var="type 3r", cls="muscle")
P("extensor_digitorum", "intertendinous_connection_4th_space", "ligament_component", "Intertendinous connection, 4th intermetacarpal space (usually type 3y)", "Most common: type 3y (tendinous, y-shaped).", ["hirai2001"], ev="cadaver n=548", var="type 3y", cls="muscle")
P("extensor_digiti_minimi", "two_slips", "insertion_point", "Extensor digiti minimi tendon: two slips", "The extensor digiti minimi tendon consisted of 2 slips (most common pattern).", ["hirai2001"], ev="cadaver n=548")
P("extensor_hood", "oblique_retinacular_ligament", "ligament_component", "Oblique retinacular ligament (Landsmeer)", "Functionally present in only 40-50 % of fingers (over 90 % on the ulnar side of the ring finger); when absent a proximal osteocapsular ligament is present.", ["shrewsbury1977"], cls="tendon", ev="dissection n=64 fingers", var="40-50 %")
P("abductor_pollicis_longus", "tendon_slips", "insertion_point", "Tendon slips (accessory slips)", "Single tendon in 20/48 forearms, double 9, triple 8, quadruple 5, five slips in 6; 93 % reach the first metacarpal, 7 % the trapezium. Another series: accessory slips in 18/20 hands (90 %), 3-6 slips; mean three slips in 6 forearms.", ["deshmukh2023", "lamas2026", "thandoni2024"],
  ev="cadaver n=48; n=20; n=6", var="1-5 slips", anchor=dict(bone="metacarpal_1", landmark="base of first metacarpal (93 %); trapezium (7 %)"))
P("first_dorsal_compartment", "separate_epb_subcompartment", "fascial_passage", "First dorsal compartment: separate EPB subcompartment", "A separate extensor pollicis brevis compartment was present in 4 of 6 forearms; the superficial radial nerve crossed the compartment in 2.", ["thandoni2024"], cls="tendon", ev="cadaver n=6",
  passes=dict(kind="tendon", traversing=["abductor_pollicis_longus", "extensor_pollicis_brevis"], through="first dorsal compartment of the extensor retinaculum"))

# =================================================================== FASCIAL PASSAGES (limbs)
