    P("extensor_retinaculum", f"compartment_{k}", "fascial_passage", f"Extensor retinaculum compartment {k}: {tends}", f"One of the 6 tunnels of the extensor retinaculum (septal attachments on the radius measured; septum 1/2 largest, 3/4 smallest). The tendon content per compartment is textbook, not stated in the abstract.", ["iwamoto2006", "gray42"], ver="unverified",
      cls="fascia", ev="cadaver n=34 wrists (count of 6 verified)", passes=dict(kind="tendon", traversing=[], traversing_text=tends, through="extensor retinaculum of the wrist"), z=["zan_extensor_retinaculum_of_wrist_{s}"] if k == 1 else [])
